def svg_defs():
    out = ['<svg width="0" height="0" style="position:absolute" aria-hidden="true"><defs>']
    for k, v in I.items():
        out.append(
            f'<symbol id="i-{k}" viewBox="0 0 24 24" fill="none" stroke="currentColor" '
            f'stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round">{v}</symbol>')
    for k, v in PARTS.items():
        out.append(
            f'<symbol id="p-{k}" viewBox="0 0 72 72" fill="none" stroke="currentColor" '
            f'stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">{v}</symbol>')
    out.append('</defs></svg>')
    return ''.join(out)


def ico(name, cls='', size=None):
    s = f' style="width:{size}px;height:{size}px"' if size else ''
    c = f' class="{cls}"' if cls else ''
    return f'<svg{c}{s} aria-hidden="true"><use href="#i-{name}"/></svg>'


def part(name, cls=''):
    c = f' class="{cls}"' if cls else ' class="part"'
    return f'<svg{c} aria-hidden="true"><use href="#p-{name}"/></svg>'
